begin;
do $$
declare uid uuid; cid uuid; cid2 uuid; a uuid; b uuid; other_id uuid; hu uuid=gen_random_uuid(); su uuid=gen_random_uuid(); p jsonb; caught boolean;
begin
 select user_id into uid from public.payroll_members where role='admin' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 cid=(public.payroll_api('company_create','{"name":"Shift QA rollback"}')->>'id')::uuid;
 cid2=(public.payroll_api('company_create','{"name":"Shift other QA rollback"}')->>'id')::uuid;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid,'SHIFT-A','Shift A','shift-a@example.invalid','Teaching','2026-10-01') returning id into a;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid,'SHIFT-B','Shift B','shift-b@example.invalid','Support','2026-10-01') returning id into b;
 insert into public.payroll_staff(company_id,code,name,email,department,joining_date) values(cid2,'SHIFT-C','Shift C','shift-c@example.invalid','Teaching','2026-10-01') returning id into other_id;
 insert into public.payroll_attendance(company_id,staff_id,work_date,status,in_time,out_time,shift_snapshot) values(cid,a,'2026-10-02','present','08:00','14:30','{"start":"08:00"}');
 p=jsonb_build_object('company_id',cid,'staff_ids',jsonb_build_array(a),'department','Teaching','shift_name','School','shift_start','08:00','shift_end','14:30','break_minutes',30,'late_grace',0,'early_grace',0);
 perform public.payroll_assign_shifts(p);
 if not exists(select 1 from public.payroll_staff where id=a and shift_start='08:00' and shift_end='14:30') or not exists(select 1 from public.payroll_staff where id=b and shift_start='09:00') then raise exception 'Selected-only assignment failed';end if;
 caught=false;begin perform public.payroll_assign_shifts(p||jsonb_build_object('staff_ids',jsonb_build_array(a,b),'shift_start','07:00'));exception when others then caught=true;end;
 if not caught or not exists(select 1 from public.payroll_staff where id=a and shift_start='08:00') then raise exception 'Department mismatch or partial write';end if;
 caught=false;begin perform public.payroll_assign_shifts(p||jsonb_build_object('staff_ids',jsonb_build_array(a,other_id)));exception when others then caught=true;end;
 if not caught then raise exception 'Tenant crossing';end if;
 caught=false;begin perform public.payroll_assign_shifts(p||jsonb_build_object('staff_ids',jsonb_build_array(a,a)));exception when others then caught=true;end;
 if not caught then raise exception 'Duplicate selection';end if;
 caught=false;begin perform public.payroll_assign_shifts(p||'{"staff_ids":[]}');exception when others then caught=true;end;
 if not caught then raise exception 'Empty selection';end if;
 caught=false;begin perform public.payroll_assign_shifts(p||'{"shift_end":"08:00"}');exception when others then caught=true;end;
 if not caught then raise exception 'Invalid shift';end if;
 insert into auth.users(id,email,email_confirmed_at) values(hu,'shift-hr@example.invalid',now()),(su,'shift-staff@example.invalid',now());
 insert into public.payroll_members values(cid,hu,'hr'),(cid,su,'staff');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',hu,'role','authenticated')::text,true);
 perform public.payroll_assign_shifts((p-'department')||jsonb_build_object('staff_ids',jsonb_build_array(a,b),'shift_start','22:00','shift_end','06:00'));
 if (select count(*) from public.payroll_staff where company_id=cid and shift_start='22:00')<>2 then raise exception 'HR bulk night shift failed';end if;
 if not exists(select 1 from public.payroll_attendance where staff_id=a and shift_snapshot='{"start":"08:00"}'::jsonb and in_time='08:00') then raise exception 'Historical attendance changed';end if;
 update public.payroll_staff set status='separated' where id=b;
 caught=false;begin perform public.payroll_assign_shifts((p-'department')||jsonb_build_object('staff_ids',jsonb_build_array(a,b)));exception when others then caught=true;end;
 if not caught then raise exception 'Separated staff assigned';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',su,'role','authenticated')::text,true);
 caught=false;begin perform public.payroll_assign_shifts(p);exception when others then caught=true;end;
 if not caught then raise exception 'Staff privilege escalation';end if;
end$$;
rollback;
select 'PASS: department and staff selection, atomic validation, HR access, staff denial, tenant isolation, night shift and attendance history' as result;
